Value does not conform to Shape [ rdf:type sh:NodeShape ; sh:class nltl:hullBoundaryPoint ; sh:property [ sh:minCount Literal("1", datatype=xsd:integer) ; sh:node [ rdf:type sh:NodeShape ; sh:class qudt:QuantityValue ; sh:property [ sh:datatype xsd:decimal ; sh:maxInclusive Literal("7", datatype=xsd:decimal) ; sh:minCount Literal("1", datatype=xsd:integer) ; sh:minInclusive Literal("7", datatype=xsd:decimal) ; sh:path qudt:numericValue ], [ sh:hasValue unit:DEG ; sh:minCount Literal("1", datatype=xsd:integer) ; sh:path qudt:unit ] ; sh:sparql [ sh:message Literal("The shell inclination angle quantity must have numericValue exactly 7 and unit http://qudt.org/vocab/unit/DEG.") ; sh:select Literal("
                            PREFIX qudt: <http://qudt.org/schema/qudt/>
                            PREFIX unit: <http://qudt.org/vocab/unit/>
                            PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
                            SELECT $this
                            WHERE {
                                {
                                    $this qudt:numericValue ?value .
                                    FILTER (?value != "7"^^xsd:decimal)
                                }
                                UNION
                                {
                                    $this qudt:unit ?unitValue .
                                    FILTER (?unitValue != unit:DEG)
                                }
                            }
                        ") ] ] ; sh:path nltl:shellInclinationAngle ] ]. See details for more information.

